        private static void ByteToBase_stPenAlarm(Array dst, byte[] src, int len = 1, int wordOffset = 0)
        {
            int[] indices = NewIndices(dst);
            int offset = wordOffset;
            for (int i = 0; i < len; i++)
            {
                stPenAlarm elemTmp = new stPenAlarm();
                NextIndices(dst, indices);
                ByteTo_stPenAlarm(ref elemTmp, src, len, wordOffset);
                dst.SetValue(elemTmp, indices);
                wordOffset += stPenAlarm_WSIZE;
            }
        }
