        private static void ByteToBase_stPolishAlarm(Array dst, byte[] src, int len = 1, int wordOffset = 0)
        {
            int[] indices = NewIndices(dst);
            int offset = wordOffset;
            for (int i = 0; i < len; i++)
            {
                stPolishAlarm elemTmp = new stPolishAlarm();
                NextIndices(dst, indices);
                ByteTo_stPolishAlarm(ref elemTmp, src, len, wordOffset);
                dst.SetValue(elemTmp, indices);
                wordOffset += stPolishAlarm_WSIZE;
            }
        }
